// Finds the smallest element in a non-empty vector.
// Precondition: `s` is non-empty.
pub fn find_smallest(s: Vec<i32>) -> i32 {
    // Initialize with the first element so the candidate is always equal to
    // one of the processed elements (invariant holds from the start).
    let (&first, rest) = s
        .split_first()
        .expect("precondition violated: input vector must be non-empty");

    let mut min = first;
    for &x in rest.iter() {
        if x < min {
            min = x;
        }
    }
    min
}

